const first = $input.first().json;
const html = first.data ?? "";

// ---- offers: strip markup, regex the discount patterns
const clean = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;|&#160;/g, " ")
  .replace(/\s+/g, " ")
  .trim();
const offers = [];
const seen = new Set();
const re = /([A-Z][A-Za-z0-9'&.\- ]{3,60}?)\s*(?:[-\u2013\u2014:|]\s*)?(?:get\s+|up\s+to\s+)?(\d{1,2})\s*%\s*(off|discount|cashback)?/gi;
let m;
while ((m = re.exec(clean)) !== null && offers.length < 20) {
  const merchant = m[1].trim().split(/\s{2,}/)[0].slice(0, 32);
  const key = merchant.toLowerCase();
  if (seen.has(key) || merchant.length < 3) continue;
  seen.add(key);
  offers.push({ merchant, value: Number(m[2]), cashback: /cashback/i.test(m[3] || "") });
}

// ---- images: unwrap jsonValue.value JSON strings, absolutize site-relative srcs
let imgs = [];
const jv = first.jsonValue && first.jsonValue.value !== undefined ? first.jsonValue.value : first.jsonValue;
if (jv) {
  try {
    const parsed = typeof jv === "string" ? JSON.parse(jv) : jv;
    const arr = Array.isArray(parsed) ? parsed : (parsed && (parsed.images || parsed.items)) || [];
    imgs = arr.map(x => (typeof x === "string" ? x : (x && (x.src || x.url || x.image)) || "")).filter(Boolean);
  } catch (e) { /* not JSON — fall back to regex */ }
}
if (!imgs.length) {
  const srcRe = /(?:src|data-src)=["']([^"']+\.(?:jpg|jpeg|png|webp))/gi;
  while ((m = srcRe.exec(html)) !== null) imgs.push(m[1]);
}
const absolutize = (s) => {
  if (/^https?:\/\//i.test(s)) return s;
  let p = String(s).replace(/^-+/, "");
  if (!p.startsWith("/")) p = "/" + p;
  return "https://www.alrajhibank.com" + p;
};
imgs = imgs.map(absolutize);

const withImages = offers.map((o, i) => ({ ...o, image: imgs.length ? imgs[i % imgs.length] : "" }));
return [{ json: { offers: withImages, imageCount: imgs.length, pageChars: clean.length } }];

const TARGET = "https://www.alrajhibank.com.sa/en/personal/cards/credit-cards/card-offers";
const { offers, imageCount, pageChars } = $input.first().json;
const now = new Date();
const norm = offers.map((o, i) => ({
  id: "alrajhi-" + o.merchant.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 40) + "-" + i,
  ext_id: o.merchant.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 48) + "-" + o.value,
  merchant: o.merchant,
  headline: o.merchant + " \u2014 " + o.value + "% " + (o.cashback ? "cashback" : "off") + " for Al Rajhi card holders",
  discount_label: "\u2212" + o.value + "%",
  value: o.value,
  kind: o.cashback ? "cashback" : "percent",
  category: "online",
  bank: "Al Rajhi Bank",
  card: /infinite/i.test(o.merchant) ? "Visa Infinite" : /signature/i.test(o.merchant) ? "Signature Visa" : "All credit tiers",
  image: o.image || "",
  cards: ["Al Rajhi credit cards"],
  link: TARGET,
  expires_at: null,
  terms: ["Parsed by the onlydeals-alrajhi n8n workflow \u2014 open the link for full terms."],
  last_seen: now.toISOString()
}));
const payload = {
  version: "offer.v1",
  generatedAt: now.toISOString(),
  generator: "n8n:onlydeals-alrajhi",
  sources: [{
    id: "alrajhi",
    name: "Al Rajhi Bank",
    status: norm.length ? "live" : "error",
    count: norm.length,
    note: norm.length + " offers \u00b7 " + imageCount + " images \u00b7 " + pageChars + " chars parsed",
    at: now.getTime()
  }],
  offers: norm
};
return [{ json: { items: norm, payload, count: norm.length } }];

// flatten output — one item per offer row, each carrying last_seen
const { items } = $input.first().json;
return items.map(o => ({ json: o }));

